 document.body.classList.add('ardennes-active');document.getElementById('viewLevel').textContent='NORMANDY | ST. LO OPERATION';
 const shell=e('div');shell.id='ardennesWorkspace';shell.className='normandy-operation';
 shell.innerHTML='<aside class="operation-command" aria-label="Command hierarchy workflow"><a href="index.html">Return to Atlas overview</a><h2>Normandy command hierarchy</h2><p>29 June 1944. Authored operation HQ and regiment, separate from the 8 June snapshot.</p><nav id="operationHierarchy" aria-label="Headquarters"></nav><div id="commandApp"></div></aside><div class="operation-splitter" role="separator" tabindex="0" aria-label="Resize command pane"></div><main class="operation-map"><section id="operationTime" aria-label="Campaign timeline"></section><div class="operation-tools"><button id="operationFit">Fit operation</button><span>Wheel: zoom | Space + drag or middle drag: pan</span></div><svg id="operationSvg" viewBox="0 0 1000 420" role="img" aria-label="Normandy command and supply map"></svg><details id="operationInformation"><summary>Map details</summary><p>Authored command locations and supply route. Situation boards retain local battlefield coordinates; they are not a geographical refinement of this diagram.</p></details><section id="campaignSituationSurface" hidden></section></main><div class="operation-splitter" role="separator" tabindex="0" aria-label="Resize Situation Cards pane"></div><aside id="operationSituations" aria-label="Campaign Situation Cards"></aside>';
 document.body.append(shell);const $=id=>document.getElementById(id),root=$('commandApp'),cards=$('operationSituations'),host=$('campaignSituationSurface'),map=$('operationSvg');
