 const state=()=>R.get()?.operation;
 const select=(panel,label,values,value,change)=>{const l=e('label',label),n=e('select');n.setAttribute('aria-label',label);for(const [v,text]of values){const o=e('option',text);o.value=v;n.append(o);}n.value=value;n.onchange=()=>change(n.value);l.append(n);panel.append(l);};
