 function next(panel){const s=state();if(!s.queue.length)return;const at=Math.min(...s.queue.map(x=>x.at)),names={order:'order arrival',prepared:'preparation complete',dispatch:'supply dispatch',arrival:'supply delivery',reserve:'reserve arrival'},label=s.queue.filter(x=>x.at===at).map(x=>names[x.kind]).join(' and ');panel.append(e('p','Next: '+label+' at '+M.clock(at)),b('Advance to '+label+' ('+M.clock(at)+')',()=>action('advance')));}
 function choose(id){if(!['HQ','M04'].includes(id)){error=id==='depot'?'Normandy Forward Depot supplies St. Lo via the marked road.':id==='reserve'?'R1 contains two additional Sherman formation counters.':'Supplies travel from Normandy Forward Depot to St. Lo supply point.';render();return;}if(mounted)window.CampaignSituationScreen.close();selected=id;viewTime=null;render();}
